DROP TABLE IF EXISTS diagnormal;
CREATE TABLE diagnormal (ID INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, Reihenfolge INT NOT NULL, Typ VARCHAR(12) NOT NULL, Kanonisch VARCHAR(80) NOT NULL, Muster VARCHAR(2000) NOT NULL COMMENT 'PCRE, auf Kleinschreibung ohne Bindestriche angewendet', Bemerkung VARCHAR(255)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
